namespace QuantForge.Core;public sealed record AndroidResearchReadinessCard(string DatasetFingerprint,string StrategyFingerprint,bool DatasetReady,bool SessionReady,bool ReliabilityReady,bool StrategyReady,bool Ready,string Status,bool CanSubmitOrders);public static class AndroidResearchReadinessCardRules{public static AndroidResearchReadinessCard Create(ResearchGateBundle gates){ResearchGateBundleRules.Validate(gates);var dataset=gates.Dataset.StructurallyValidated;var session=gates.SessionCoverage.Report.Authoritative&&gates.SessionCoverage.Report.MissingMinutes==0&&gates.SessionCoverage.Report.OutsideSessionMinutes==0;var reliability=gates.Reliability.Admissible;var strategy=gates.Strategy.Envelope.State==StrategyAdmissionState.Admitted;var ready=dataset&&session&&reliability&&strategy;return new(gates.Dataset.DatasetFingerprint,gates.Strategy.Envelope.Manifest.SourceFingerprint,dataset,session,reliability,strategy,ready,ready?"Research ready":"Research blocked",false);}}
